B.Lj=new A.bL("gem_museum","Grand Egyptian Museum (GEM)","\u0627\u0644\u0645\u062a\u062d\u0641 \u0627\u0644\u0645\u0635\u0631\u064a \u0627\u0644\u0643\u0628\u064a\u0631","cairo","Giza","\u0627\u0644\u062c\u064a\u0632\u0629",B.j5,"The world's largest archaeological museum, featuring the complete 5,000-piece Tutankhamun collection and hanging obelisk at the foot of the Pyramids.","\u0623\u0643\u0628\u0631 \u0645\u062a\u062d\u0641 \u0623\u062b\u0631\u064a \u0641\u064a \u0627\u0644\u0639\u0627\u0644\u0645 \u064a\u0642\u0639 \u0628\u062c\u0648\u0627\u0631 \u0627\u0644\u0623\u0647\u0631\u0627\u0645\u0627\u062a\u060c \u064a\u0636\u0645 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0644\u0644\u0645\u0644\u0643 \u062a\u0648\u062a \u0639\u0646\u062e \u0622\u0645\u0648\u0646 \u0648\u0627\u0644\u0645\u0633\u0644\u0629 \u0627\u0644\u0645\u0639\u0644\u0642\u0629.",1000,22,"08:30","18:00",210,"Grand Egyptian Museum Official Portal (egymonuments.gov.eg)","2025-02-01",29.9947,31.1181,u.d,!0,!0,"Book tickets online in advance. Guided main atrium and grand staircase tours recommended.","\u0627\u062d\u062c\u0632 \u0627\u0644\u062a\u0630\u0627\u0643\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0645\u0633\u0628\u0642\u0627\u064b \u0644\u062a\u0641\u0627\u062f\u064a \u0637\u0648\u0627\u0628\u064a\u0631 \u0627\u0644\u0634\u0628\u0627\u0643.")
B.LK=new A.bL("nmec_mummies","National Museum of Egyptian Civilization (NMEC)","\u0627\u0644\u0645\u062a\u062d\u0641 \u0627\u0644\u0642\u0648\u0645\u064a \u0644\u0644\u062d\u0636\u0627\u0631\u0629 \u0627\u0644\u0645\u0635\u0631\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0645\u064a\u0627\u0648\u0627\u062a","cairo","Cairo (Fustat)","\u0627\u0644\u0642\u0627\u0647\u0631\u0629 (\u0627\u0644\u0641\u0633\u0637\u0627\u0637)",B.j5,"State-of-the-art museum housing the 22 Royal Mummies of ancient Pharaohs including Ramesses II and Hatshepsut in climate-controlled tomb vaults.","\u0645\u062a\u062d\u0641 \u0639\u0627\u0644\u0645\u064a \u062d\u062f\u064a\u062b \u064a\u0636\u0645 \u0642\u0627\u0639\u0629 \u0627\u0644\u0645\u0648\u0645\u064a\u0627\u0648\u0627\u062a \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u0640 \u0662\u0662 \u0644\u0623\u0639\u0638\u0645 \u0641\u0631\u0627\u0639\u0646\u0629 \u0645\u0635\u0631 \u0628\u0645\u0627 \u0641\u064a\u0647\u0645 \u0631\u0645\u0633\u064a\u0633 \u0627\u0644\u062b\u0627\u0646\u064a \u0648\u062d\u062a\u0634\u0628\u0633\u0648\u062a.",500,11,"09:00","17:00",150,"NMEC Official Authority (nmec.gov.eg)","2025-01-20",30.008,31.2483,u.n,!0,!0,"No photography allowed inside the Royal Mummies Hall to preserve preservation conditions.","\u0627\u0644\u062a\u0635\u0648\u064a\u0631 \u0645\u0645\u0646\u0648\u0639 \u062f\u0627\u062e\u0644 \u0642\u0627\u0639\u0629 \u0627\u0644\u0645\u0648\u0645\u064a\u0627\u0648\u0627\u062a \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0626\u0629 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0628\u0647\u0627.")
B.LJ=new A.bL("saqqara_djoser","Saqqara Step Pyramid of Djoser","\u0647\u0631\u0645 \u0633\u0642\u0627\u0631\u0629 \u0627\u0644\u0645\u062f\u0631\u062c (\u0647\u0631\u0645 \u0632\u0648\u0633\u0631)","cairo","Giza (Saqqara)","\u0627\u0644\u062c\u064a\u0632\u0629 (\u0633\u0642\u0627\u0631\u0629)",B.c5,"The world's oldest major stone structure built by architect Imhotep for King Djoser in 2670 BC, plus the Serapeum bull tombs.","\u0623\u0642\u062f\u0645 \u0628\u0646\u064a\u0627\u0646 \u062d\u062c\u0631\u064a \u0645\u062c\u0648\u0641 \u0641\u064a \u0627\u0644\u0639\u0627\u0644\u0645 \u0634\u064a\u062f\u0647 \u0627\u0644\u0645\u0647\u0646\u062f\u0633 \u0625\u0645\u062d\u0648\u062a\u0628 \u0644\u0644\u0645\u0644\u0643 \u0632\u0648\u0633\u0631\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0644\u0645\u0642\u0627\u0628\u0631 \u0627\u0644\u0633\u0631\u0627\u0628\u064a\u0648\u0645 \u0627\u0644\u0639\u062c\u064a\u0628\u0629.",450,10,"08:00","17:00",180,"Saqqara Archaeological Inspectorate","2025-01-18",29.8713,31.2163,u.z,!0,!1,"Combine Saqqara with the nearby Bent Pyramid of Dahshur for a full day ancient necropolis tour.","\u062f\u0645\u062c \u0633\u0642\u0627\u0631\u0629 \u0645\u0639 \u0623\u0647\u0631\u0627\u0645\u0627\u062a \u062f\u0647\u0634\u0648\u0631 \u0627\u0644\u0645\u062c\u0627\u0648\u0631\u0629 \u0641\u064a \u062c\u0648\u0644\u0629 \u064a\u0648\u0645 \u0643\u0627\u0645\u0644 \u064a\u0645\u0646\u062d\u0643 \u062a\u062c\u0631\u0628\u0629 \u0623\u062b\u0631\u064a\u0629 \u0641\u0631\u064a\u062f\u0629.")
